//! Java mods' world generation: in a dimension whose generation the mods change (Biomes O'
//! Plenty's biomes through TerraBlender, a mod's ores in vanilla's biomes), chunks are
//! generated by vanilla's own chunk steps on the Java side (`HorizonWorldgen`), with the mods'
//! biome sources, surface rules and features, and read back as vanilla saves a chunk.
//! Everything else of the generator (far terrain, structure searches, spawn) stays Horizon's
//! own [`VanillaTerrain`], and a dimension the mods leave alone is all Horizon's.

use horizon_client::biome::Biomes;
use horizon_client::chunk::Chunk;
use horizon_client::streaming::{ChunkGenerator, LodSampler, Proto};
use horizon_client::vanillagen::VanillaTerrain;
use horizon_world::registry::BlockRegistry;
use std::sync::{Arc, OnceLock};

/// How long the first chunk waits for Java and Fabric to start (they start beside the world).
const JAVA_START: std::time::Duration = std::time::Duration::from_secs(300);

/// The Java mods' jars as data packs whose structures Horizon's generator reads (new
/// structures and their sets, biome tags, templates, template pools, processor lists, the
/// features pools place), lowest first in jar order: a mod replacing vanilla's templates
/// (The Sift's ancient city centres) or adding structures to a dimension it otherwise leaves
/// alone (Towns and Towers' villages) changes the structures Horizon generates as a data
/// pack would. Fabric adds each mod's data as a pack below the world's.
pub(super) fn mod_structure_packs() -> Vec<horizon_client::datapack::DataPack> {
    super::java_mods::mod_jars()
        .1
        .iter()
        .filter_map(|jar| {
            let name = jar.file_name()?.to_string_lossy();
            match horizon_client::datapack::DataPack::archive(&format!("mod/{name}"), jar) {
                Ok(pack) => Some(pack.structures_only()),
                Err(e) => {
                    log::warn!("Java mods: {name}'s data not read for structures: {e}");
                    None
                }
            }
        })
        .collect()
}

/// What makes Horizon's generator over a world's data packs (`VanillaTerrain::for_world_with`),
/// for far terrain with the mods' noise ([`NoiseLand`]).
pub(super) struct NoiseWorld {
    /// The worldgen bundle (`<resources>/worldgen`).
    pub(super) bundle: std::path::PathBuf,
    pub(super) resources: std::path::PathBuf,
    pub(super) world_root: std::path::PathBuf,
    pub(super) enabled_features: Vec<String>,
    pub(super) preset: String,
    /// The game's biomes with the world's packs over them.
    pub(super) biomes: Arc<Biomes>,
    pub(super) seed: i64,
}

/// The land of a dimension whose noise the mods change (Tectonic's density functions): the
/// mods' noise as a data pack (`HorizonNoiseExport`) over the world's, and Horizon's own
/// generator made with it, which far terrain samples instead of vanilla's noise. Made once,
/// on the first far column asked after the mods generate the dimension; None when the noise
/// is vanilla's or can't be written as vanilla data.
struct NoiseLand {
    dimension: Arc<str>,
    registry: &'static BlockRegistry,
    world: NoiseWorld,
    terrain: OnceLock<Option<Arc<VanillaTerrain>>>,
}

impl NoiseLand {
    fn terrain(&self) -> Option<&Arc<VanillaTerrain>> {
        self.terrain.get_or_init(|| self.make()).as_ref()
    }

    fn make(&self) -> Option<Arc<VanillaTerrain>> {
        let started = std::time::Instant::now();
        let dir = self
            .world
            .world_root
            .join("data")
            .join("horizon_java_noise")
            .join(self.dimension.replace(':', "_"));
        let _ = std::fs::remove_dir_all(&dir);
        match horizon_jvm::events::worldgen_lod_noise(&self.dimension, &dir) {
            Ok(horizon_jvm::events::LodNoise::Written) => {}
            Ok(horizon_jvm::events::LodNoise::Vanilla) => return None,
            Ok(horizon_jvm::events::LodNoise::Failed(why)) | Err(why) => {
                log::warn!(
                    "Java mods: {}'s far terrain keeps vanilla's noise, not the mods': {why}",
                    self.dimension
                );
                return None;
            }
        }
        let w = &self.world;
        let packs = horizon_client::datapack::discover_with_features(&w.world_root, &w.resources);
        let enabled =
            horizon_client::datapack::enabled_ids(&w.world_root, &packs, &w.enabled_features);
        let ours = horizon_client::datapack::DataPack::folder("horizon/java_noise", &dir);
        let mut list: Vec<&horizon_client::datapack::DataPack> = enabled
            .iter()
            .filter_map(|id| packs.iter().find(|p| &p.id == id))
            .collect();
        list.push(&ours);
        let (overrides, warnings) =
            horizon_client::datapack::worldgen_overrides(&list, |b| w.biomes.contains(b));
        for warning in warnings {
            log::warn!("Java mods: far terrain's noise: {warning}");
        }
        match VanillaTerrain::for_world_with(
            &w.bundle,
            &overrides,
            self.registry,
            &w.biomes,
            w.seed,
            &w.preset,
            &self.dimension,
            false,
        ) {
            Ok(terrain) => {
                log::info!(
                    "Java mods: {}'s far terrain from the mods' noise (made in {} ms)",
                    self.dimension,
                    started.elapsed().as_millis()
                );
                Some(Arc::new(terrain))
            }
            Err(e) => {
                log::warn!(
                    "Java mods: {}'s far terrain keeps vanilla's noise: the mods' doesn't load: {e}",
                    self.dimension
                );
                None
            }
        }
    }
}

/// A dimension's generator when Java mods are installed: Horizon's, or the mods' chunk by chunk.
pub(super) struct JavaTerrain {
    inner: Arc<VanillaTerrain>,
    dimension: Arc<str>,
    seed: i64,
    structures: bool,
    /// The world's folder (where the mods' saved data is, which their worldgen set-up reads).
    world: std::path::PathBuf,
    /// Whether the mods generate this dimension, asked once (the first chunk waits for Java).
    modded: Arc<OnceLock<bool>>,
    /// Whether that generator is a mod's own and not on the noise (One Block's): Horizon's
    /// noise says nothing of its land, so far terrain is the generator's base columns.
    custom: Arc<OnceLock<bool>>,
    /// Whether Horizon's noise fills the Java protos (asked once the mods generate it).
    horizon_noise: OnceLock<bool>,
    /// Far terrain's land when the mods change the noise.
    land: Arc<NoiseLand>,
    registry: &'static BlockRegistry,
    /// The game's assets, for the save tables reading the chunks' ticks (made once).
    assets: Arc<horizon_client::assets::Assets>,
    tables: OnceLock<horizon_client::save::SaveTables>,
    biomes: Arc<Biomes>,
}

/// A chunk held on the Java side, at TERRAIN, then FEATURES once decorated.
struct JavaProto {
    dimension: Arc<str>,
    x: i32,
    z: i32,
    token: i64,
    decorated: bool,
    /// Finished: the Java side let it go already.
    taken: bool,
}

impl Drop for JavaProto {
    /// A proto Horizon drops unfinished (the player moved away) is let go on the Java side.
    fn drop(&mut self) {
        if !self.taken
            && let Err(e) =
                horizon_jvm::events::worldgen_forget(&self.dimension, self.x, self.z, self.token)
        {
            log::warn!("Java mods' worldgen: forgetting {} {}: {e}", self.x, self.z);
        }
    }
}

impl JavaTerrain {
    /// Horizon's generator for `dimension`, as the mods' when Java mods are installed.
    pub(super) fn wrap(
        inner: Arc<VanillaTerrain>,
        dimension: &str,
        seed: i64,
        structures: bool,
        world: &std::path::Path,
        assets: Arc<horizon_client::assets::Assets>,
        biomes: Arc<Biomes>,
        noise_world: NoiseWorld,
    ) -> Option<Self> {
        let registry = assets.registry;
        if !super::java_mods::has_java_mods() {
            return None;
        }
        // Until the mods say whether they generate it, the spawn search waits.
        inner.expect_oracle();
        Some(Self {
            inner,
            dimension: Arc::from(dimension),
            seed,
            structures,
            world: world.to_path_buf(),
            modded: Arc::new(OnceLock::new()),
            custom: Arc::new(OnceLock::new()),
            horizon_noise: OnceLock::new(),
            land: Arc::new(NoiseLand {
                dimension: Arc::from(dimension),
                registry,
                world: noise_world,
                terrain: OnceLock::new(),
            }),
            registry,
            assets,
            tables: OnceLock::new(),
            biomes,
        })
    }

    fn modded(&self) -> bool {
        *self.modded.get_or_init(|| {
            let modded = self.start();
            if !modded {
                self.custom.get_or_init(|| false);
                self.inner.no_oracle();
            }
            modded
        })
    }

    fn start(&self) -> bool {
        if !super::java_mods::wait_for_java(JAVA_START) {
            log::warn!(
                "Java mods: not running, so {} generates as vanilla's",
                self.dimension
            );
            return false;
        }
        // Structures Horizon's generator can't make here (a mod's own structure type:
        // Friends & Foes' citadel): the mods generate the dimension, with them.
        let cannot = if self.structures {
            self.inner.unsupported_structures()
        } else {
            Vec::new()
        };
        match horizon_jvm::events::worldgen_start(
            &self.dimension,
            self.seed,
            self.structures,
            &self.world,
            &cannot,
        ) {
            Ok(true) => {
                let origin = horizon_jvm::events::worldgen_origin(&self.dimension)
                    .ok()
                    .flatten();
                // A generator of the mod's own, not on the noise (One Block's void): far
                // terrain from its columns; on the noise (Grid World's), Horizon's land.
                self.custom
                    .get_or_init(|| origin.is_some_and(|o| o.custom && !o.noise));
                // /locate biome and maps of places not generated yet ask the mods too, and
                // the spawn comes from their generator's origin.
                self.inner.set_biome_oracle(Arc::new(JavaBiomes {
                    dimension: self.dimension.clone(),
                    biomes: self.biomes.clone(),
                    origin,
                }));
                true
            }
            Ok(false) => false,
            Err(e) => {
                log::warn!("Java mods' worldgen: {}: {e}", self.dimension);
                false
            }
        }
    }

    /// The chunk the Java side gave (vanilla's save form), as Horizon's final column.
    fn read(&self, x: i32, z: i32, bytes: &[u8]) -> Option<Chunk> {
        let (root, _) =
            horizon_world::nbt::read_named(bytes, horizon_world::nbt::Limits::default()).ok()?;
        // With the save tables, the chunk's scheduled ticks come too: the fluids and blocks
        // the features scheduled (a lake's water, a spring's lava) flow once it is live.
        let tables = self
            .tables
            .get_or_init(|| horizon_client::save::SaveTables::new(&self.assets));
        let mut chunk = horizon_client::save::decode_with(
            &root,
            self.registry,
            &self.biomes,
            Some(tables),
            self.inner.layout(),
        )?;
        if (chunk.x, chunk.z) != (x, z) {
            return None;
        }
        // ProtoChunk's post-processing marks (vanilla's PostProcessing: per section, packed
        // x | y << 4 | z << 8): fluids an aquifer or a feature left to update, as
        // LevelChunk.postProcessGeneration does once the chunk is live.
        if let Some(horizon_world::nbt::Tag::List(sections)) = root.tag.get("PostProcessing") {
            let base = match root.tag.get("yPos") {
                Some(horizon_world::nbt::Tag::Int(y)) => *y,
                _ => horizon_client::chunk::MIN_Y >> 4,
            };
            for (i, marks) in sections.iter().enumerate() {
                let horizon_world::nbt::Tag::List(marks) = marks else {
                    continue;
                };
                let sy = (base + i as i32) * 16;
                for mark in marks {
                    if let horizon_world::nbt::Tag::Short(p) = mark {
                        let p = i32::from(*p);
                        chunk.postprocess.push([
                            x * 16 + (p & 15),
                            sy + ((p >> 4) & 15),
                            z * 16 + ((p >> 8) & 15),
                        ]);
                    }
                }
            }
        }
        // Structures' mobs (a villager in its house), as a generated proto chunk holds them.
        if let Some(horizon_world::nbt::Tag::List(entities)) = root.tag.get("entities") {
            chunk.entities = entities.clone();
        }
        for s in &mut chunk.sections {
            Arc::make_mut(s).compact();
        }
        chunk.fresh = true;
        Some(chunk)
    }
}

impl ChunkGenerator for JavaTerrain {
    type Worker = <VanillaTerrain as ChunkGenerator>::Worker;

    fn worker(&self) -> Self::Worker {
        self.inner.worker()
    }

    /// Far terrain is Horizon's (the mods change biomes and features, rarely the land's
    /// shape), with the mods' biomes once they generate the dimension.
    fn lod_sampler(self: Arc<Self>) -> Box<dyn LodSampler> {
        Box::new(JavaLod {
            inner: self.inner.clone().lod_sampler(),
            land: self.land.clone(),
            land_sampler: None,
            modded: self.modded.clone(),
            custom: self.custom.clone(),
            registry: self.registry,
            materials: Arc::new(OnceLock::new()),
            oracle: JavaBiomes {
                dimension: self.dimension.clone(),
                biomes: self.biomes.clone(),
                origin: None,
            },
        })
    }

    fn lod_surface(
        &self,
        worker: &mut Self::Worker,
        x: i32,
        z: i32,
    ) -> Option<horizon_client::lod::Surface> {
        if self.custom.get() == Some(&true) {
            return None;
        }
        self.inner.lod_surface(worker, x, z)
    }

    fn prepare_loaded(&self, worker: &mut Self::Worker, chunk: &Chunk) {
        self.inner.prepare_loaded(worker, chunk);
    }

    fn proto(&self, worker: &mut Self::Worker, x: i32, z: i32) -> Proto {
        if !self.modded() {
            return self.inner.proto(worker, x, z);
        }
        let horizon_noise = *self.horizon_noise.get_or_init(|| {
            horizon_jvm::events::worldgen_noise_from_horizon(&self.dimension).unwrap_or(false)
        });
        // Horizon's noise (the same router, aquifers and ore veins as vanilla's), so Java only
        // runs the surface, carvers and what follows on the mods' biomes.
        let fill = horizon_noise
            .then(|| {
                let chunk = {
                    let _timed = super::java_profile::Timed::named("worldgen horizon noise");
                    self.inner.noise_chunk(worker, x, z)
                }?;
                let _timed = super::java_profile::Timed::named("worldgen horizon noise copy");
                Some(self.inner.noise_fill_of(&chunk, x, z))
            })
            .flatten();
        let made = {
            let _timed = super::java_profile::Timed::named("worldgen proto");
            match fill {
                Some(fill) => horizon_jvm::events::worldgen_proto_filled(
                    &self.dimension,
                    x,
                    z,
                    &fill.palette,
                    &fill.blocks,
                    &fill.postprocess,
                ),
                None => horizon_jvm::events::worldgen_proto(&self.dimension, x, z),
            }
        };
        match made {
            Ok(Some(token)) => Box::new(JavaProto {
                dimension: self.dimension.clone(),
                x,
                z,
                token,
                decorated: false,
                taken: false,
            }),
            Ok(None) => {
                log::warn!(
                    "Java mods' worldgen: chunk {x} {z} failed; Horizon's generator makes it"
                );
                self.inner.proto(worker, x, z)
            }
            Err(e) => {
                log::warn!("Java mods' worldgen: chunk {x} {z}: {e}; Horizon's generator makes it");
                self.inner.proto(worker, x, z)
            }
        }
    }

    fn decorates(&self) -> bool {
        true
    }

    fn decorate(&self, worker: &mut Self::Worker, region: &mut [Proto; 9]) {
        let Some(center) = region[4].downcast_mut::<JavaProto>() else {
            return self.inner.decorate(worker, region);
        };
        if let Err(e) = {
            let _timed = super::java_profile::Timed::named("worldgen decorate");
            horizon_jvm::events::worldgen_decorate(&center.dimension, center.x, center.z)
        } {
            log::warn!(
                "Java mods' worldgen: decorating {} {}: {e}",
                center.x,
                center.z
            );
        }
        center.decorated = true;
    }

    fn is_decorated(&self, proto: &Proto) -> bool {
        match proto.downcast_ref::<JavaProto>() {
            Some(p) => p.decorated,
            None => self.inner.is_decorated(proto),
        }
    }

    fn light_view(&self, proto: &Proto) -> Option<Chunk> {
        match proto.downcast_ref::<JavaProto>() {
            Some(_) => None,
            None => self.inner.light_view(proto),
        }
    }

    /// A Java proto isn't saved: it is generated again (decoration a neighbour wrote into it
    /// before it was dropped is lost, at the edge of where the player went).
    /// A Java proto dropped unfinished is saved as Horizon saves its own: its neighbours'
    /// features wrote into it (half a tree at the edge of where the player went), and made
    /// again it would lose those writes.
    fn saved_proto(&self, proto: &Proto) -> Option<horizon_client::chunk::SavedProto> {
        let Some(p) = proto.downcast_ref::<JavaProto>() else {
            return self.inner.saved_proto(proto);
        };
        let bytes = horizon_jvm::events::worldgen_snapshot(&p.dimension, p.x, p.z, p.token)
            .ok()
            .flatten()?;
        let column = self.read(p.x, p.z, &bytes)?;
        let (root, _) =
            horizon_world::nbt::read_named(&bytes, horizon_world::nbt::Limits::default()).ok()?;
        let list = |key: &str| match root.tag.get(key) {
            Some(horizon_world::nbt::Tag::List(l)) => l.clone(),
            _ => Vec::new(),
        };
        Some(horizon_client::chunk::SavedProto {
            column,
            decorated: matches!(
                root.tag.get("horizon:decorated"),
                Some(horizon_world::nbt::Tag::Byte(1))
            ),
            block_entities: list("block_entities"),
            entities: list("entities"),
        })
    }

    /// The saved proto's blocks, block entities, entities and decoration put back onto the
    /// Java proto made again.
    fn restore_proto(&self, proto: &mut Proto, saved: horizon_client::chunk::SavedProto) {
        let Some(p) = proto.downcast_mut::<JavaProto>() else {
            return self.inner.restore_proto(proto, saved);
        };
        let column = &saved.column;
        let min_y = horizon_client::chunk::MIN_Y;
        let height = horizon_client::chunk::HEIGHT;
        let mut palette: Vec<String> = Vec::new();
        let mut index: std::collections::HashMap<u32, i32> = std::collections::HashMap::new();
        let mut blocks = vec![0i32; height as usize * 256];
        for (i, slot) in blocks.iter_mut().enumerate() {
            let (x, z, y) = (
                (i & 15) as i32,
                ((i >> 4) & 15) as i32,
                min_y + (i >> 8) as i32,
            );
            let state = column.block(x, y, z);
            *slot = *index.entry(state.0).or_insert_with(|| {
                palette.push(state_name(self.registry, state));
                palette.len() as i32 - 1
            });
        }
        let snbt = |tags: &[horizon_world::nbt::Tag]| -> Vec<String> {
            tags.iter().map(horizon_client::snbt::to_snbt).collect()
        };
        if let Err(e) = horizon_jvm::events::worldgen_restore(
            &p.dimension,
            p.x,
            p.z,
            p.token,
            &palette,
            min_y,
            &blocks,
            &snbt(&saved.block_entities),
            &snbt(&saved.entities),
            saved.decorated,
        ) {
            log::warn!("Java mods' worldgen: restoring {} {}: {e}", p.x, p.z);
            return;
        }
        p.decorated |= saved.decorated;
    }

    fn finish(&self, proto: Proto) -> Chunk {
        let mut proto = match proto.downcast::<JavaProto>() {
            Ok(p) => p,
            Err(other) => return self.inner.finish(other),
        };
        let (x, z) = (proto.x, proto.z);
        let bytes = {
            let _timed = super::java_profile::Timed::named("worldgen finish");
            horizon_jvm::events::worldgen_finish(&proto.dimension, x, z, proto.token)
        };
        proto.taken = true;
        match bytes {
            Ok(Some(bytes)) => self.read(x, z, &bytes).unwrap_or_else(|| {
                log::warn!("Java mods' worldgen: chunk {x} {z} came back unreadable");
                Chunk::empty(x, z)
            }),
            Ok(None) => {
                log::warn!("Java mods' worldgen: chunk {x} {z} came back empty");
                Chunk::empty(x, z)
            }
            Err(e) => {
                log::warn!("Java mods' worldgen: chunk {x} {z}: {e}");
                Chunk::empty(x, z)
            }
        }
    }
}

/// A dimension's biomes as the mods' biome source gives them (`HorizonWorldgen.biomes`).
struct JavaBiomes {
    dimension: Arc<str>,
    biomes: Arc<Biomes>,
    /// The mods' generator's origin and spawn height (`HorizonWorldgen.origin`).
    origin: Option<horizon_jvm::events::WorldgenOrigin>,
}

impl JavaBiomes {
    /// Horizon's biome table ids of the mods' biomes at block positions (None: not theirs).
    fn ids(&self, blocks: &[[i32; 3]]) -> Option<Vec<u16>> {
        let quarts: Vec<[i32; 3]> = blocks.iter().map(|b| b.map(|v| v >> 2)).collect();
        let names = horizon_jvm::events::worldgen_biomes(&self.dimension, &quarts).ok()??;
        Some(
            names
                .iter()
                .map(|n| n.as_deref().map_or(0, |n| self.biomes.id(n)))
                .collect(),
        )
    }
}

impl horizon_client::vanillagen::BiomeOracle for JavaBiomes {
    fn spawn_origin(&self) -> Option<((i32, i32), i32)> {
        self.origin.map(|o| ((o.x, o.z), o.height))
    }

    fn noise_biomes(&self, quarts: &[[i32; 3]]) -> Option<Vec<Option<String>>> {
        horizon_jvm::events::worldgen_biomes(&self.dimension, quarts)
            .ok()
            .flatten()
    }

    fn locate_structure(
        &self,
        selector: &str,
        from: [i32; 3],
        radius: i32,
    ) -> Option<Option<(String, [i32; 3])>> {
        horizon_jvm::events::worldgen_locate_structure(&self.dimension, selector, from, radius)
            .ok()
            .flatten()
    }

    fn find_closest_biome(
        &self,
        search: &horizon_world::worldgen::generator::BiomeSearch<'_>,
    ) -> Option<Option<(String, [i32; 3])>> {
        let possible = horizon_jvm::events::worldgen_possible_biomes(&self.dimension)
            .ok()
            .flatten()?;
        let names: Vec<String> = possible
            .into_iter()
            .filter(|n| (search.allowed)(n))
            .collect();
        if names.is_empty() {
            return Some(None);
        }
        horizon_jvm::events::worldgen_find_biome(
            &self.dimension,
            &names,
            search.origin,
            search.radius,
            search.horizontal,
            search.vertical,
        )
        .ok()
        .flatten()
    }
}

/// Far terrain of a dimension the mods may generate: Horizon's columns (its noise is the
/// mods' land) with each column's biome (its colours) and top block the mods' once they
/// generate it; a mod's own generator's base columns when it isn't on the noise.
struct JavaLod {
    inner: Box<dyn LodSampler>,
    /// The mods' noise's land, when they change it ([`NoiseLand`]), and its sampler.
    land: Arc<NoiseLand>,
    land_sampler: Option<Box<dyn LodSampler>>,
    modded: Arc<OnceLock<bool>>,
    custom: Arc<OnceLock<bool>>,
    registry: &'static BlockRegistry,
    /// What the land is made of ([`JavaLod::materials`]), shared by the samplers.
    materials:
        Arc<OnceLock<Option<std::collections::HashSet<horizon_world::registry::BlockStateId>>>>,
    oracle: JavaBiomes,
}

impl JavaLod {
    fn modded(&self) -> bool {
        self.modded.get() == Some(&true)
    }

    /// The sampler of the land's shape: the mods' noise's when they change it, else Horizon's.
    fn land(&mut self) -> &mut Box<dyn LodSampler> {
        if self.land_sampler.is_none()
            && self.modded()
            && let Some(terrain) = self.land.terrain()
        {
            self.land_sampler = Some(terrain.clone().lod_sampler());
        }
        self.land_sampler.as_mut().unwrap_or(&mut self.inner)
    }

    /// A mod's own generator not on the noise makes the dimension (a void with one block):
    /// Horizon's columns would show land that isn't there.
    fn custom(&self) -> bool {
        self.custom.get() == Some(&true)
    }

    /// The mod's generator's columns (ChunkGenerator.getBaseColumn) at `at`, with the mods'
    /// biomes: runs of blocks, the top one the surface.
    fn own_columns(&self, at: &[(i32, i32)]) -> Vec<horizon_client::lod::Column> {
        let runs = {
            let _timed = super::java_profile::Timed::named("worldgen far columns");
            horizon_jvm::events::worldgen_lod_columns(&self.oracle.dimension, at)
        };
        let runs = runs.ok().flatten().unwrap_or_default();
        let mut columns: Vec<horizon_client::lod::Column> = at
            .iter()
            .enumerate()
            .map(|(i, _)| {
                let mut column = horizon_client::lod::Column::default();
                for (from, to, state) in runs.get(i).into_iter().flatten() {
                    let Some(state) = parse_state(self.registry, state) else {
                        continue;
                    };
                    column.spans.push(horizon_client::lod::Span {
                        min: *from as i16,
                        max: *to as i16,
                        state,
                        biome: 0,
                        // Open sky, no block light.
                        light: 0xf0,
                    });
                }
                if let Some(top) = column.spans.last() {
                    column.surface = Some(horizon_client::lod::Surface {
                        height: i32::from(top.max),
                        state: top.state,
                        water: None,
                        biome: 0,
                    });
                }
                column
            })
            .collect();
        let tops: Vec<[i32; 3]> = columns
            .iter()
            .zip(at)
            .map(|(c, &(x, z))| [x, c.surface.map_or(64, |s| s.height - 1), z])
            .collect();
        if let Some(ids) = self.oracle.ids(&tops) {
            for (column, id) in columns.iter_mut().zip(ids) {
                if let Some(surface) = column.surface.as_mut() {
                    surface.biome = id;
                }
                for span in &mut column.spans {
                    span.biome = id;
                }
            }
        }
        columns
    }

    /// The blocks the land is made of (the surface rules' and the default block), asked once.
    fn materials(
        &self,
    ) -> Option<&std::collections::HashSet<horizon_world::registry::BlockStateId>> {
        self.materials
            .get_or_init(|| {
                let names = horizon_jvm::events::worldgen_lod_materials(&self.oracle.dimension)
                    .ok()
                    .flatten()?;
                Some(
                    names
                        .iter()
                        .filter_map(|n| parse_state(self.registry, n))
                        .collect(),
                )
            })
            .as_ref()
    }

    /// Each column's land top block as the mods' surface rules make it
    /// (`HorizonWorldgen.lodTops`): Horizon's rules are vanilla's, the mods' biomes have their
    /// own (BOP's). The land top is the highest run of a block the rules give (or stone):
    /// trees, plants and water above it stay.
    fn tops(&self, columns: &mut [&mut horizon_client::lod::Column], at: &[(i32, i32)]) {
        let Some(materials) = self.materials() else {
            return;
        };
        let mut asked = Vec::new();
        let mut water = Vec::new();
        let mut which = Vec::new();
        for (i, (column, &(x, z))) in columns.iter().zip(at).enumerate() {
            let Some(k) = column
                .spans
                .iter()
                .rposition(|s| materials.contains(&s.state))
            else {
                continue;
            };
            // Vanilla's biomes have vanilla's rules: Horizon's own columns are those.
            let biome = self.oracle.biomes.get(column.spans[k].biome);
            if biome.name.starts_with("minecraft:") {
                continue;
            }
            let top = i32::from(column.spans[k].max) - 1;
            // Water right over the land: the height it reaches.
            let mut over = i32::MIN;
            if let Some(next) = column.spans.get(k + 1)
                && next.min == column.spans[k].max
                && let Some(surface) = column.surface
                && let Some((height, _)) = surface.water
                && height > top
            {
                over = height;
            }
            asked.push([x, top, z]);
            water.push(over);
            which.push((i, k));
        }
        if asked.is_empty() {
            return;
        }
        let states = {
            let _timed = super::java_profile::Timed::named("worldgen far tops");
            horizon_jvm::events::worldgen_lod_tops(&self.oracle.dimension, &asked, &water)
        };
        let Some(states) = states.ok().flatten() else {
            return;
        };
        for (((i, k), top), state) in which.into_iter().zip(asked).zip(states) {
            let Some(state) = state.and_then(|s| parse_state(self.registry, &s)) else {
                continue;
            };
            // Land stays land (a rule's water or air is for a column's shape, not its top).
            if !materials.contains(&state) {
                continue;
            }
            let column = &mut *columns[i];
            let span = column.spans[k];
            if span.state == state {
                continue;
            }
            if let Some(surface) = column.surface.as_mut()
                && surface.height == i32::from(span.max)
            {
                surface.state = state;
            }
            // The run's top block alone takes the new state.
            let y = top[1] as i16;
            if span.max - span.min == 1 {
                column.spans[k].state = state;
            } else {
                column.spans[k].max = y;
                let mut spans = column.spans.to_vec();
                spans.insert(
                    k + 1,
                    horizon_client::lod::Span {
                        min: y,
                        max: y + 1,
                        state,
                        ..span
                    },
                );
                column.spans = spans.into();
            }
        }
    }

    /// Sets each column's biome to the mods' at `(x, surface, z)`.
    fn remap(&self, columns: &mut [&mut horizon_client::lod::Column], at: &[(i32, i32)]) {
        let blocks: Vec<[i32; 3]> = columns
            .iter()
            .zip(at)
            .map(|(c, &(x, z))| [x, c.surface.map_or(64, |s| s.height - 1), z])
            .collect();
        if let Some(ids) = self.oracle.ids(&blocks) {
            for (column, id) in columns.iter_mut().zip(ids) {
                if let Some(surface) = column.surface.as_mut() {
                    surface.biome = id;
                }
                for span in &mut column.spans {
                    span.biome = id;
                }
            }
        }
        self.tops(columns, at);
    }

    fn remap_one(
        &self,
        mut column: horizon_client::lod::Column,
        x: i32,
        z: i32,
    ) -> horizon_client::lod::Column {
        if self.modded() {
            self.remap(&mut [&mut column], &[(x, z)]);
        }
        column
    }
}

impl LodSampler for JavaLod {
    fn fork(&self) -> Option<Box<dyn LodSampler>> {
        Some(Box::new(JavaLod {
            inner: self.inner.fork()?,
            land: self.land.clone(),
            land_sampler: None,
            modded: self.modded.clone(),
            custom: self.custom.clone(),
            registry: self.registry,
            materials: self.materials.clone(),
            oracle: JavaBiomes {
                dimension: self.oracle.dimension.clone(),
                biomes: self.oracle.biomes.clone(),
                origin: None,
            },
        }))
    }

    fn request_detail(&mut self, chunks: &[(i32, i32)], center: [i32; 2]) {
        self.land().request_detail(chunks, center);
    }

    fn drain_details(&mut self) -> Vec<horizon_client::streaming::LodDetail> {
        let mut details = self.land().drain_details();
        if self.custom() {
            for ((cx, cz), columns) in &mut details {
                let at: Vec<(i32, i32)> = (0..256)
                    .map(|i| (*cx * 16 + (i & 15), *cz * 16 + (i >> 4)))
                    .collect();
                let mut own = self.own_columns(&at).into_iter();
                *columns = Arc::new(std::array::from_fn(|_| own.next().unwrap_or_default()));
            }
            return details;
        }
        if self.modded() {
            for ((cx, cz), columns) in &mut details {
                let mut owned = (**columns).clone();
                let at: Vec<(i32, i32)> = (0..256)
                    .map(|i| (*cx * 16 + (i & 15), *cz * 16 + (i >> 4)))
                    .collect();
                let mut refs: Vec<&mut horizon_client::lod::Column> = owned.iter_mut().collect();
                self.remap(&mut refs, &at);
                *columns = Arc::new(owned);
            }
        }
        details
    }

    fn sample(&mut self, x: i32, z: i32) -> Option<horizon_client::lod::Surface> {
        self.column(x, z).surface
    }

    fn column(&mut self, x: i32, z: i32) -> horizon_client::lod::Column {
        if self.custom() {
            return self.own_columns(&[(x, z)]).pop().unwrap_or_default();
        }
        let column = self.land().column(x, z);
        self.remap_one(column, x, z)
    }

    fn reduced_column(&mut self, x: i32, z: i32, width: i32) -> horizon_client::lod::Column {
        if self.custom() {
            return self
                .own_columns(&[(x + width / 2, z + width / 2)])
                .pop()
                .unwrap_or_default();
        }
        let column = self.land().reduced_column(x, z, width);
        self.remap_one(column, x + width / 2, z + width / 2)
    }

    fn grid(
        &mut self,
        x: i32,
        z: i32,
        stride: i32,
        side: usize,
    ) -> Vec<horizon_client::lod::Column> {
        let at: Vec<(i32, i32)> = (0..side * side)
            .map(|i| {
                (
                    x + (i % side) as i32 * stride + stride / 2,
                    z + (i / side) as i32 * stride + stride / 2,
                )
            })
            .collect();
        if self.custom() {
            return self.own_columns(&at);
        }
        let mut columns = self.land().grid(x, z, stride, side);
        if self.modded() {
            let mut refs: Vec<&mut horizon_client::lod::Column> = columns.iter_mut().collect();
            self.remap(&mut refs, &at);
        }
        columns
    }
}

/// A state as Java writes it (`minecraft:oak_log[axis=y]`, BlockStateParser.serialize).
fn parse_state(
    registry: &BlockRegistry,
    text: &str,
) -> Option<horizon_world::registry::BlockStateId> {
    let (name, properties) = match text.split_once('[') {
        Some((name, rest)) => (name, rest.strip_suffix(']')?),
        None => (text, ""),
    };
    let mut descriptor = horizon_world::chunk::BlockState {
        name: name.to_owned(),
        properties: Default::default(),
    };
    for pair in properties.split(',').filter(|p| !p.is_empty()) {
        let (k, v) = pair.split_once('=')?;
        descriptor.properties.insert(k.to_owned(), v.to_owned());
    }
    registry.resolve(&descriptor).ok()
}

/// `minecraft:oak_log[axis=y]`: a state as Java reads it.
fn state_name(registry: &BlockRegistry, state: horizon_world::registry::BlockStateId) -> String {
    let Some(s) = registry.state(state) else {
        return "minecraft:air".into();
    };
    if s.properties.is_empty() {
        return s.name.clone();
    }
    let props: Vec<String> = s
        .properties
        .iter()
        .map(|(k, v)| format!("{k}={v}"))
        .collect();
    format!("{}[{}]", s.name, props.join(","))
}
